  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/44997', 'network_profile', 'affiliate', 'Portland Leather Goods'' own Awin merchant profile (US, merchant 44997) states a 9% default commission and a 30-day cookie, and gives the affiliate team contact as makenna@porotlandleathergoods.com - spelled exactly that way on the profile. The profile also notes a private Facebook group of over 50,000 active members. No earnings-cap statement appears, so the cap is unknown.', 'verified', now());
