  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.instagram.com/p/DdossbnoKoT/', 'listing', 'ugc_collab', 'A widely shared marketing breakdown reports Portland Leather recruited roughly 500 fan affiliates who produced about 3,800 videos - creator scale in the hundreds, which under the directory standard is honestly unknown saturation, not low.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 13, 13, 7, 4, '{"compensation": "9% default on Awin, with a creator route reported at 13% rising to 17% in tiers.", "contact_access": "Named affiliate-team email published on the brand''s own Awin profile, plus a public creator application.", "credibility": "Established US maker with its own stores and a large verified social following.", "niche_fit": "Handbags, totes and leather accessories are core fashion content, and the bags are heavily featured in travel and everyday-carry posts.", "opportunity_availability": "Open Awin program plus an actively promoted creator crew.", "ugc_evidence": "A named creator program with an application, a 50,000-member fan group and hundreds of fan affiliates making thousands of videos."}'::jsonb);
