  insert into public.brands (name, website, description, country, status) values ('Wedderspoon', 'https://wedderspoon.com', 'Manuka honey and bee-powered wellness brand selling raw Manuka honey, honey lozenges, pops and related natural products through its own US storefront and major retailers, built around ''wellness rituals'' and clean, traceable ingredients.', 'United States', 'published') returning id into bid;
