  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Wedderspoon Affiliate Program (The Wedderspoon Hive)', 'https://wedderspoon.com/pages/wedderspoon-affiliate-program', 'https://wedderspoon.com/pages/wedderspoon-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://wedderspoon.com/pages/wedderspoon-affiliate-program', 'official_site', 'affiliate', 'Wedderspoon''s own affiliate program page (''Join the Wedderspoon Hive'') offers affiliates a 10% commission on every purchase made through their link plus a 10% discount code for their audience and a Manuka welcome kit; the page''s Register Now buttons link to Awin''s publisher signup (ui.awin.com), so the program runs on Awin. The page states no earnings cap and no creator count, so commission_cap and creator_saturation are recorded as unknown.', 'verified', now());
