  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 12, 6, 7, 4, '{"niche_fit": "Manuka honey sits across wellness, natural remedies and pantry content - a good fit for wellness and clean-living creators.", "ugc_evidence": "The brand runs a named creator-facing affiliate community (the Wedderspoon Hive) with a welcome kit and audience discount codes, though no separate UGC program was found.", "compensation": "Published on the brand''s own page: 10% commission plus a 10% follower discount code - mid-range, and fully first-party verified.", "contact_access": "A public program page with registration via Awin exists, but no published partnerships email was found.", "opportunity_availability": "Applications are open from the brand''s own program page (brand reviews fit before approval).", "credibility": "Long-running Manuka honey brand with national retail distribution and a US storefront."}'::jsonb);
