  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://letsliveitup.com/pages/affiliates', 'official_site', 'affiliate', 'Live It Up''s own affiliate page (''Become a Live it Up Partner'') recruits video creators, writers, influencers and ambassadors with commissions, first access to new products and exclusive offers; its APPLY HERE button links to app.impact.com, so the program runs on Impact. The brand''s help center likewise confirms ''We love partnering with creators, influencers'' and links the same page. No rate, cap or creator count is stated on the brand page.', 'verified', now());
