  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.garagegymreviews.com/live-it-up-super-greens-review', 'listing', 'general', 'Garage Gym Reviews'' brand coverage notes Live It Up (formerly Enso Superfoods) sells Super Greens DTC in the US, and carries an editor''s note that in January 2026 the company recalled certain Super Greens lots over potential Salmonella contamination - flagged here for reviewer awareness.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 12, 6, 7, 3, '{"niche_fit": "Greens powders are a staple wellness-creator product with strong review and routine content formats.", "ugc_evidence": "The brand actively recruits creators and ambassadors on its own page and socials (ambassador calls promising free product plus commission).", "compensation": "Published network rate of 10% per sale on Impact, with the brand page confirming commissions plus product access.", "contact_access": "A public partner application page exists, but no published partnerships email was found.", "opportunity_availability": "Applications are open from the brand''s own page into Impact.", "credibility": "Established DTC greens brand with national media coverage, marked down because of a January 2026 recall of certain Super Greens lots reported by review outlets."}'::jsonb);
