  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bullybunches.com/pages/affiliate-program', 'official_site', 'affiliate', 'Bully Bunches'' own affiliate page invites creators to ''earn up to 10% commission'' via a personal code/link, with a 10% first-purchase code for followers, PayPal payouts, and requirements to hold an active social account and share photos/videos. ''Up to'' is a rate ceiling, so no single rate is recorded.', 'verified', now());
