  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 9, 11, 8, 3, '{"compensation": "The brand publishes ''up to 10%'' commission \u2014 a ceiling rather than a confirmed base rate \u2014 so the rate is null and compensation scores mid-low.", "contact_access": "Public affiliate page with on-site signup plus a published support email.", "credibility": "Smaller DTC brand on Shopify Plus with a 67K-follower Instagram presence; no major retail distribution verified.", "niche_fit": "Natural dog chews are a highly demonstrable, pet-creator-friendly product category.", "opportunity_availability": "Affiliate signup is publicly open on the brand''s own site; ambassador cohorts run on seasonal searches.", "ugc_evidence": "Structured ambassador searches with defined monthly content deliverables, plus an open affiliate program requiring creators to post photos/videos."}'::jsonb);
